import { randomUUID } from "node:crypto";
import type { Order, OrderState } from "../domain/order";
import type { Product } from "../domain/product";
import type { Clock, IdGenerator, OrderRepository, ProductRepository } from "../domain/repositories";

export class InMemoryProductRepository implements ProductRepository {
  private readonly items = new Map<string, Product>();

  findById(id: string): Product | undefined {
    return this.items.get(id);
  }

  findAll(): Product[] {
    return [...this.items.values()];
  }

  save(product: Product): void {
    this.items.set(product.id, product);
  }
}

export class InMemoryOrderRepository implements OrderRepository {
  private readonly items = new Map<string, Order>();

  findById(id: string): Order | undefined {
    return this.items.get(id);
  }

  findAll(): Order[] {
    return [...this.items.values()];
  }

  findByState(state: OrderState): Order[] {
    return this.findAll().filter((o) => o.state === state);
  }

  save(order: Order): void {
    this.items.set(order.id, order);
  }
}

export class SystemClock implements Clock {
  now(): Date {
    return new Date();
  }
}

export class UuidGenerator implements IdGenerator {
  next(): string {
    return randomUUID();
  }
}

